  // Warm-up: six enqueue ports at full rate, never redirect. Rob decides
  // acceptance itself (io_enq_canAccept is an OUTPUT), so filling the ROB
  // is exactly what writes all 160 entries once. Writebacks sweep robIdx
  // so the exu/store debug arrays get written too.
  int unsigned wb_sweep = 0;

  // ---- phase 0：开跑先来一次 redirect，把随机初值冲掉 ----------------
  // ★为什么需要它（实测，不是推测）★：+vcs+initreg+random 那三轮
  // (seed 1/7/42, 200k 拍) 全部 checks=0 —— 热身从未完成，
  // enq_seen 只填到约 59/160，wb_seen 全 0(phase B 压根没启动)。
  // 原因是 phase A 的前提在随机初值下不成立：条目的 uopNum/valid 随机，
  // 已在队里的"垃圾条目"永远不满足 uopNum==0，deqPtr 冻住、队列排不空，
  // enqPtr 走不满一圈。+vcs+initreg+0 时这些寄存器起始为 0，所以看不到。
  // 修法：复位刚放开就发一拍 redirect(level=1, robIdx=0)，让 ROB 自己
  // 走回/作废掉那些垃圾条目，进入一个确定的空队列，再开始 phase A。
  // redirect 是**输入**，两侧收到的完全一样，不构成"用 golden 的状态造激励"。
  int unsigned flush_cyc = 0;
  wire phase_0 = flush_cyc < 400;

  // Warm-up runs in TWO phases, because the two obligations fight each
  // other if you try to satisfy them at once. Diagnosed by watching the
  // DUT (+diag), not by reasoning about it -- the first two guesses were
  // both wrong:
  //   A: fill enq_seen. enqPtr must pass 156, which needs entries to
  //      RETIRE (allowEnqueue deasserts with RenameWidth of headroom).
  //      An entry retires at uopNum == 0, and uopNum is loaded from the
  //      input io_enq_req_<p>_bits_numWB (golden Rob.sv:115386). So
  //      phase A drives numWB = 0 and keeps ALL writebacks invalid:
  //      entries are born committable, the queue drains, the pointer
  //      wraps, and every one of the 160 entries gets written.
  //      ★Why numWB=1 + writebacks did NOT work★: uopNum -= (number of
  //      writebacks matching this robIdx). Driving all 25 exu ports at
  //      the same robIdx decrements a uopNum of 1 by 25, and the 7-bit
  //      field WRAPS to 104 instead of reaching 0 -- so the entry never
  //      became committable and deqPtr froze at 1. Observed as
  //      enqPtr=156 deqPtr=1 allowEnq=0 held for thousands of cycles.
  //   B: fill wb_seen. Sweep (port, robIdx) over all 25x160 pairs, one
  //      port at a time so uopNum cannot underflow.
  wire phase_b = (&enq_seen) & ~phase_0;   // continuous: a `bit` cannot take assign

