        $display("checks=0 errors=1  (warm-up failure counts as an error)");
        $display("TEST FAILED");
        $finish;
      end
      $display("checks=%0d errors=%0d", checks, errors);
      // ★判绿字符串必须由 tb 打出来★：ut_common.mk 的 `run` 靠
